#nullable enable // autogenerated

using System;
using MVZ2Logic.UI;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace MVZ2.UI.Addons
{
    public class ResourcePackItem : MonoBehaviour
    {
        public void UpdateItem(ResourcePackViewData viewData)
        {
            nameText.text = viewData.name;
            descriptionText.text = viewData.description;
            icon.SetSprite(viewData.icon);
            outdatedObject.SetActive(viewData.outdated);
            SetToggled(viewData.selected);
        }
        public void SetToggled(bool value)
        {
            toggle.SetIsOnWithoutNotify(value);
        }
        private void Awake()
        {
            toggle.onValueChanged.AddListener(v => OnToggled?.Invoke(this, v));
        }
        public event Action<ResourcePackItem, bool>? OnToggled;
        [SerializeField]
        private Toggle toggle = null!;
        [SerializeField]
        private TextMeshProUGUI nameText = null!;
        [SerializeField]
        private TextMeshProUGUI descriptionText = null!;
        [SerializeField]
        private GameObject outdatedObject = null!;
        [SerializeField]
        private ImageResolver icon = null!;
    }
    public struct ResourcePackViewData
    {
        public string name;
        public string description;
        public Sprite icon;
        public bool outdated;
        public bool selected;
    }
}
